/* FinOps, Capacity Planning, Backup & DR */
(function () {
  const { h, raw, ui, chart, data: D } = COC, { STAFF, ALL } = COC.roleSets;

  /* ================= FINOPS ================= */
  COC.actions['fo.rs'] = id => { const r = D.rightsize.find(x => x.id === id); r.done = true; COC.audit('Rightsizing applied', r.name + ' ' + r.from + '→' + r.to); COC.toast(r.name + ' resized → saves ' + ui.fmt$(r.save) + '/mo', 'ok'); COC.refresh(); };
  COC.actions['fo.buy'] = i => { const c = D.commit[+i]; c.done = true; COC.audit('Commitment purchase queued', c.what); COC.toast('Queued: ' + c.what, 'ok'); COC.refresh(); };
  COC.actions['fo.idle'] = id => { D.idle = D.idle.filter(x => x.id !== id); COC.audit('Idle resource removed', id); COC.toast('Deleted idle resource', 'ok'); COC.refresh(); };
  COC.actions['fo.an'] = id => { const a = D.anomalies.find(x => x.id === id); COC.modal({ title: 'Why did it jump?', body: h`<p><b>${a.text}</b></p><p>${a.why}</p><p class="mut">Detected by: 14-day seasonal baseline, z-score 3.4</p>`, actions: [{ label: 'Close' }, { label: 'Create alert rule', primary: true, fn: () => { COC.audit('Budget alert created from anomaly', id); COC.toast('Alert rule created', 'ok'); } }] }); };
  COC.actions['fo.csv'] = () => { COC.download('chargeback.csv', COC.csv([['team', 'tenant', 'project', 'aws', 'azure', 'gcp', 'ocp', 'total'], ...cb().map(r => [r.team, r.tenant, r.project, r.aws, r.azure, r.gcp, r.ocp, r.aws + r.azure + r.gcp + r.ocp])]), 'text/csv'); COC.audit('Chargeback report exported'); };
  COC.actions['fo.by'] = v => { COC.tabs.fo_by = v; COC.refresh(); };
  const cb = () => COC.byTenant(D.chargeback);
  COC.register({ id: 'finops', name: 'FinOps & Cost Intelligence', icon: '💰', phase: 2, roles: ALL, render() {
    const t = COC.tabs.finops || 'over', rs = COC.byTenant(D.resources), tot = rs.reduce((a, b) => a + b.cost, 0);
    const saveRS = D.rightsize.filter(r => !r.done).reduce((a, b) => a + b.save, 0), saveCM = D.commit.filter(c => !c.done).reduce((a, b) => a + b.save, 0), saveID = D.idle.reduce((a, b) => a + b.save, 0);
    let body;
    if (t === 'over') body = h`<div class="card"><h2>Daily spend – last 30 days</h2>${chart.line(D.clouds.map(c => ({ name: c, color: COC.cloudColor[c], data: D.costSeries[c] })), { labels: D.days, fmt: v => '$' + v, title: 'daily cost' })}</div>
      <div class="card"><h2>Cost anomalies</h2>${ui.table([{ h: 'Cloud', f: a => a.cloud }, { h: 'Anomaly', f: a => a.text }, { h: 'Impact', f: a => ui.badge(a.delta, 'bad') }, { h: '', f: a => ui.btn('Why?', 'fo.an', a.id, { s: 1 }) }], D.anomalies)}</div>`;
    else if (t === 'rs') body = h`<div class="card flat">${ui.table([{ h: 'Resource', f: r => r.name }, { h: 'Cloud', f: r => r.cloud }, { h: 'CPU avg', num: 1, f: r => ui.badge(r.cpu + '%', 'warn') }, { h: 'Recommendation', f: r => h`${r.from} → <b>${r.to}</b>` }, { h: 'Saves', num: 1, f: r => ui.fmt$(r.save) + '/mo' }, { h: '', f: r => r.done ? ui.badge('applied', 'ok') : ui.btn('Apply', 'fo.rs', r.id, { s: 1, p: 1, w: 1 }) }], COC.byTenant(D.rightsize), { empty: 'No rightsizing candidates for this tenant.' })}</div>`;
    else if (t === 'ri') body = h`<div class="card flat">${ui.table([{ h: 'Cloud', f: c => c.cloud }, { h: 'Recommendation', f: c => c.what }, { h: 'Coverage', f: c => c.detail }, { h: 'Est. savings', num: 1, f: c => ui.fmt$(c.save) + '/mo' }, { h: '', f: (c, i) => c.done ? ui.badge('queued', 'ok') : ui.btn('Purchase', 'fo.buy', i, { s: 1, p: 1, w: 1 }) }], D.commit)}</div>`;
    else if (t === 'bud') body = h`<div class="card flat">${ui.table([{ h: 'Tenant', f: b => b.tenant }, { h: 'Budget', num: 1, f: b => ui.fmt$(b.budget) }, { h: 'Spent', f: b => h`<div style="width:140px">${ui.bar(b.spent / b.budget * 100)}</div>${ui.fmt$(b.spent)}` }, { h: 'Forecast', num: 1, f: b => ui.fmt$(b.forecast) }, { h: 'Status', f: b => b.forecast > b.budget ? ui.badge('over by ' + ui.fmt$(b.forecast - b.budget), 'bad') : ui.badge('on track', 'ok') }], COC.byTenant(D.budgets.map(b => ({ ...b }))).filter(b => COC.state.tenant === COC.TENANTS[0] || b.tenant === COC.state.tenant))}</div>`;
    else if (t === 'cb') { const by = COC.tabs.fo_by || 'team', g = {}; cb().forEach(r => { const k = r[by]; g[k] = (g[k] || 0) + r.aws + r.azure + r.gcp + r.ocp; }); body = h`<div class="row" style="margin-bottom:8px"><span class="mut">Group by</span>${ui.select('fo-by', ['team', 'tenant', 'project'], by, 'fo.by')}<button class="btn" data-act="fo.csv">⬇ Export CSV</button></div><div class="grid g21"><div class="card flat">${ui.table([{ h: by, f: r => r[0] }, { h: 'Cost / mo', num: 1, f: r => ui.fmt$(r[1]) }], Object.entries(g).sort((a, b) => b[1] - a[1]))}</div><div class="card">${chart.bars(Object.entries(g).sort((a, b) => b[1] - a[1]).slice(0, 8).map(([l, v]) => ({ label: l, value: v })), { fmt: ui.fmt$ })}</div></div>`; }
    else body = h`<div class="card flat">${ui.table([{ h: 'Resource', f: r => r.res }, { h: 'Why idle', f: r => r.what }, { h: 'Cloud', f: r => r.cloud }, { h: 'Waste', num: 1, f: r => ui.fmt$(r.save) + '/mo' }, { h: '', f: r => ui.btn('Delete', 'fo.idle', r.id, { s: 1, d: 1, w: 1 }) }], D.idle, { empty: 'No idle resources 🎉' })}</div>`;
    return h`<div class="ph"><div class="grow"><h1>FinOps &amp; Cost Intelligence</h1><p class="sub">Anomalies, rightsizing, commitments, budgets &amp; forecast, chargeback/showback and idle-resource clean-up.</p></div></div>
      <div class="grid g4">${ui.kpi('Monthly spend', ui.fmt$(tot))}${ui.kpi('Rightsizing savings', ui.fmt$(saveRS), 'per month', 'good')}${ui.kpi('Commitment savings', ui.fmt$(saveCM), 'per month', 'good')}${ui.kpi('Idle waste', ui.fmt$(saveID), 'per month', 'bad')}</div>
      ${ui.tabs('finops', [['over', 'Overview & anomalies'], ['rs', 'Rightsizing'], ['ri', 'RI / Savings Plans'], ['bud', 'Budgets & forecast'], ['cb', 'Chargeback / showback'], ['idle', 'Idle resources']], t)}${body}`;
  } });

  /* ================= CAPACITY ================= */
  const CP = { clients: 5, growth: 6, target: 'eks-prod-eu' };
  COC.actions['cap.set'] = (v, el) => { CP[el.dataset.arg] = el.dataset.arg === 'target' ? v : +v; COC.refresh(); };
  COC.actions['cap.apply'] = i => { COC.audit('Autoscaling recommendation applied', D.scaling[+i][0]); COC.toast('Applied to ' + D.scaling[+i][0], 'ok'); };
  COC.register({ id: 'capacity', name: 'Capacity Planning', icon: '📈', phase: 4, roles: STAFF, render() {
    const hist = D.capHist, g = CP.growth / 100, proj = []; let v = hist[hist.length - 1]; for (let i = 0; i < 6; i++) { v = v * (1 + g); proj.push(Math.round(v)); }
    const series = [{ name: 'Actual utilisation %', data: hist.concat(Array(6).fill(null)) }, { name: 'Forecast', color: 'var(--warn)', dash: 1, data: Array(11).fill(null).concat([hist[11]], proj) }];
    const cross = proj.findIndex(p => p >= 100), months = cross < 0 ? '> 6' : cross + 1;
    const base = D.headroom.find(x => x.name === CP.target), perClient = 1.8, extra = CP.clients * perClient, newNodes = Math.ceil(extra * base.nodes / 100 * 1.3), cost = newNodes * 310;
    return h`<div class="ph"><div class="grow"><h1>Capacity Planning &amp; Forecasting</h1><p class="sub">Trend forecasts, what-if modelling, headroom tracking and autoscaling recommendations.</p></div></div>
      <div class="grid g21"><div class="card"><h2>Fleet utilisation forecast</h2><label class="f" style="max-width:340px">Monthly growth: <b>${CP.growth}%</b><input type="range" min="0" max="15" value="${CP.growth}" data-chg="cap.set" data-arg="growth"></label>${chart.line(series, { labels: Array.from({ length: 18 }, (_, i) => i < 12 ? 'M' + (i - 11) : '+' + (i - 11)), fmt: v => v + '%', min: 0, max: 130, hline: 100, hlabel: 'capacity', vline: 11, title: 'forecast' })}<p>At this rate you hit <b>100%</b> in <b class="${cross >= 0 && cross < 4 ? 'bad' : 'good'}">${months} months</b>${cross >= 0 ? h` — need ≈ <b>${Math.round((proj[Math.min(cross + 2, 5)] / 100) * 10) / 10}×</b> nodes within the quarter` : ''}.</p></div>
      <div class="card"><h2>What-if: onboard new clients</h2><label class="f">Target cluster${ui.select('cap-t', D.headroom.map(x => x.name), CP.target, 'cap.set', 'target')}</label><label class="f">New clients: <b>${CP.clients}</b><input type="range" min="1" max="20" value="${CP.clients}" data-chg="cap.set" data-arg="clients"></label><dl class="kv"><dt>Extra load</dt><dd>+${extra.toFixed(1)}% fleet CPU</dd><dt>Nodes needed</dt><dd><b>${newNodes}</b> (${base.nodes} → ${base.nodes + newNodes})</dd><dt>Added cost</dt><dd><b>${ui.fmt$(cost)}</b>/mo</dd><dt>Verdict</dt><dd>${base.cpu + extra > 85 ? ui.badge('needs scale-out', 'bad') : ui.badge('fits in headroom', 'ok')}</dd></dl></div></div>
      <div class="card flat"><div style="padding:14px 16px 0"><h2>Cluster headroom (right now)</h2></div>${ui.table([{ h: 'Cluster', f: c => c.name }, { h: 'Nodes', num: 1, f: c => c.nodes }, { h: 'CPU', f: c => h`<div style="width:130px">${ui.bar(c.cpu)}</div>${c.cpu}% · headroom ${100 - c.cpu}%` }, { h: 'Memory', f: c => h`<div style="width:130px">${ui.bar(c.mem)}</div>${c.mem}%` }, { h: 'Spare nodes (est.)', num: 1, f: c => Math.max(0, Math.floor((85 - c.cpu) / 100 * c.nodes)) }], D.headroom)}</div>
      <div class="card flat"><div style="padding:14px 16px 0"><h2>Auto-scaling recommendations</h2></div>${ui.table([{ h: 'Target', f: s => s[0] }, { h: 'Policy', f: s => s[1] }, { h: 'Why', f: s => s[2] }, { h: '', f: (s, i) => ui.btn('Apply', 'cap.apply', i, { s: 1, p: 1, w: 1 }) }], D.scaling)}</div>`;
  } });

  /* ================= BACKUP & DR ================= */
  COC.actions['bk.run'] = id => { const x = D.resources.find(r => r.id === id); x.backup = true; x.backupAgeH = 0; COC.audit('Backup triggered', x.name); COC.toast('Backup started for ' + x.name, 'ok'); COC.refresh(); };
  COC.actions['bk.drill'] = n => { const e = D.drEnvs.find(x => x.env === n); e.score = Math.min(100, e.score + 6); e.gaps = Math.max(0, e.gaps - 1); COC.audit('DR drill executed', n); COC.toast('DR drill passed for ' + n + ' – readiness updated', 'ok'); COC.refresh(); };
  COC.register({ id: 'backup', name: 'Backup & DR Management', icon: '💾', phase: 4, roles: ALL, render() {
    const crit = COC.byTenant(D.resources).filter(x => x.env === 'prod' && /VM|EC2|GCE|VSI|RDS|SQL/.test(x.type)), unb = crit.filter(x => !x.backup), stale = crit.filter(x => x.backup && x.backupAgeH > 48);
    return h`<div class="ph"><div class="grow"><h1>Backup &amp; DR Management</h1><p class="sub">Backup policy compliance, last-backup age, DR readiness scoring and RTO/RPO tracking.</p></div></div>
      <div class="grid g4">${ui.kpi('Critical assets', crit.length)}${ui.kpi('Not backed up', unb.length, '', unb.length ? 'bad' : 'good')}${ui.kpi('Backup older than 48h', stale.length, '', stale.length ? 'warn' : 'good')}${ui.kpi('Policy coverage', crit.length ? Math.round((crit.length - unb.length) / crit.length * 100) + '%' : '—')}</div>
      <div class="grid g4">${D.drEnvs.map(e => h`<div class="card"><h2>${e.env}</h2><div class="kpi"><div class="v ${e.score < 60 ? 'bad' : e.score < 80 ? 'warn' : 'good'}">${e.score}</div><div class="l">DR readiness · ${e.gaps} gaps</div></div>${ui.bar(e.score)}<div style="margin-top:8px">${ui.btn('Run DR drill', 'bk.drill', e.env, { s: 1, p: 1, w: 1 })}</div></div>`)}</div>
      <div class="grid g2"><div class="card flat"><div style="padding:14px 16px 0"><h2>RTO / RPO vs target</h2></div>${ui.table([{ h: 'Service', f: s => s.svc }, { h: 'RTO (min)', f: s => h`${s.rtoA} / ${s.rto} ${s.rtoA > s.rto ? ui.badge('MISS', 'bad') : ui.badge('ok', 'ok')}` }, { h: 'RPO (min)', f: s => h`${s.rpoA} / ${s.rpo} ${s.rpoA > s.rpo ? ui.badge('MISS', 'bad') : ui.badge('ok', 'ok')}` }], D.rto)}</div>
      <div class="card flat"><div style="padding:14px 16px 0"><h2>Backup status – critical prod assets</h2></div>${ui.table([{ h: 'Asset', f: x => x.name }, { h: 'Last backup', f: x => !x.backup ? ui.badge('never', 'bad') : ui.badge(x.backupAgeH + 'h ago', x.backupAgeH > 48 ? 'warn' : 'ok') }, { h: '', f: x => ui.btn('Back up now', 'bk.run', x.id, { s: 1, w: 1 }) }], crit.slice(0, 10))}</div></div>`;
  } });
})();
